import{DIMENSIONS,METRICS,VERSIONS,calculateOEI,normalizeScore}from'./scoring.mjs';import{REQUIREMENTS,FOUNDER_SECTIONS,STAFF_PROMPTS,STAFF_INTERVIEW_SECTIONS,SAMPLE_TYPES,blankDiagnosis,baseRecord,uid,validateCheckpoint,migrateCheckpoint,validateRequirement,interviewStatusAfterScheduling,projectMonthsFromWeeks,syncFounderValidationLead,skipFounderSection}from'./model.mjs';import{ENUMS,enumLabel}from'./enums.mjs';import{deriveMetrics,validateToolRecord}from'./derivations.mjs';import{assembleReport,reportMarkdown}from'./report.mjs';
const root=document.querySelector('#app');let state=null,view='overview',toast='',modal='';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const opts=(values,current)=>values.map(v=>`<option ${v===current?'selected':''}>${esc(v)}</option>`).join('');
const REQUIRED_PATHS=[
  /^validationLeads\.\d+\.(claim|status)$/,
  /^engagement\.(companyName|sampledContributors|sampledWeeks|founderWorkdays|qualifyingInterruptions|monthsSampled|toolContributors|toolWorkdays)$/,
  /^staffInterviews\.\d+\.(name|role|status|sectionResponses\.\d+)$/,
  /^staffInterviews\.\d+\.sectionQuantitative\.\d+\.\d+\.(quantitativeEstimate|confidence)$/,
  /^evidence\.\d+\.(statement|evidenceType|confidence)$/,
  /^contradictions\.\d+\.(title|sourceA|sourceB|description|resolution)$/,
  /^findings\.\d+\.(title|observation|evidenceIds|confidence)$/,
  /^compensatingMechanisms\.\d+\.(missingStructure|humanCompensation|whoCarriesIt|hiddenCost|riskIfRemoved)$/,
  /^recommendations\.\d+\.(title|level|priority|driverIds|structuralChange|evidenceBasis|expectedEffect|successSignal)$/,
  /^metricRecords\.[^.]+\.(state|confidence|evidenceBasis|sampleSize)$/,
  /^selectedDrivers\.\d+\.(title|observation|structuralEffects|operationalConsequence|selectionRationale)$/,
  /^reportDraft\.(executiveObservation|operationalImpact|immediatePriority|scoreInterpretation)$/,
  /^samples\.criticalOperations\.\d+\.(name|founderMemoryDependent)$/,
  /^samples\.decisionEvents\.\d+\.(decision|blockedPersonHours)$/,
  /^samples\.documents\.\d+\.(name|obsolescenceStatus)$/,
  /^samples\.retrievalTests\.\d+\.(informationRequested|minutesElapsed|documentFound)$/,
  /^samples\.projects\.\d+\.(name|totalEffort|forcedStops|avoidableReworkHours|realignmentEvents)$/,
  /^samples\.toolWorkflows\.\d+\.(name|avoidableMinutes)$/,
  /^samples\.tools\.\d+\.(name|purpose|classification)$/,
  /^samples\.integrations\.\d+\.(name|accurate|complete|timely|manualIntervention|outcome)$/,
  /^samples\.handoffs\.\d+\.(workTransferred|purposePresent|rationalePresent|ownerPresent|deadlinePresent|constraintsPresent|dependenciesPresent|inputsPresent|successCriteriaPresent|contextLossRating|clarificationHours)$/,
  /^samples\.onboardingCases\.\d+\.(role|actualDuration|confidence)$/
];
const conditionalMandatory=key=>{let match=key.match(/^samples\.tools\.(\d+)\.classificationReason$/);if(match)return['candidate_consolidation','operational_deadweight','insufficient_evidence'].includes(state?.samples?.tools?.[Number(match[1])]?.classification);match=key.match(/^samples\.documents\.(\d+)\.classificationReason$/);if(match)return['insufficient_evidence','not_assessed'].includes(state?.samples?.documents?.[Number(match[1])]?.obsolescenceStatus);match=key.match(/^samples\.integrations\.(\d+)\.failureReason$/);if(match)return['failed','insufficient_evidence'].includes(state?.samples?.integrations?.[Number(match[1])]?.outcome);return false};
const FIELD_HELP={
  companySize:'Approximate number of people whose work is within scope.',businessModel:'How the company creates and captures value; used to interpret operating context.',communicationPlatform:'Primary system where operational communication and escalation history can be inspected.',documentationPlatform:'Primary system expected to contain approved operational knowledge.',taskPlatform:'Primary system used to assign and track work.',confidentialityRestrictions:'Access, attribution, or reporting limits that must be respected.',practitionerNotes:'Internal context that should not appear in the client report.',practitionerNote:'Internal interpretation or follow-up note; it does not enter the client report automatically.',nextAction:'The next concrete action needed to advance the diagnosis.',notes:'Explain the operational impact of this requirement status.',alternativeSource:'A substitute source that can reduce this evidence gap.',status:'The current canonical state; used for workflow tracking and completion.',confidentialityNotes:'Attribution limits or handling instructions for this interview.',response:'Capture the participant’s substantive answer in their own language.',skipReason:'Explain why this required question or activity was not completed.',statement:'The specific fact, claim, estimate, perception, or inference this record supports.',evidenceType:'How the information is known; used to interpret its evidentiary weight.',metricIds:'Canonical metric IDs this evidence informs.',confidence:'How strongly the available source supports this value or interpretation.',clientSafeWording:'Optional client-facing copy available to the report after review.',sourceA:'The first evidence record or statement in tension.',sourceB:'The second evidence record or statement in tension.',description:'Explain exactly how the selected evidence conflicts.',resolution:'How the contradiction was reconciled or why it remains unresolved.',claim:'The founder hypothesis that direct validation will test.',quantitativeEstimate:'The numeric value asserted before direct validation.',artifactCandidate:'The document, record, workflow, or observation expected to validate the claim.',validationNotes:'What was tested, what was found, and what remains uncertain.',sampledContributors:'Contributors represented in the decision-blockage denominator.',sampledWeeks:'Length of the shared historical window used for weekly rates.',founderWorkdays:'Actual founder workdays examined for qualifying interruptions.',qualifyingInterruptions:'Total interruptions meeting the methodology definition in the sampled founder days.',monthsSampled:'The sampled-weeks window expressed in calendar months for alignment drift.',toolContributors:'Contributors represented in the tool-transition sample.',toolWorkdays:'Actual contributor workdays represented by the tool-workflow observations.',founderMemoryDependent:'Whether this operation depends primarily on knowledge held in the founder’s memory.',classificationReason:'Evidence supporting the selected classification, especially adverse or uncertain states.',decision:'The founder-level decision that blocked progress.',blockedPersonHours:'Total productive person-hours lost while waiting for the decision.',contributorsAffected:'People whose productive work was affected by the delay.',evidenceReference:'Calendar item, message, task, or interview supporting this record.',process:'The operational process this document is intended to support.',obsolescenceStatus:'Whether the document was current and immediately usable when tested.',informationRequested:'The specific operational information the participant was asked to retrieve.',minutesElapsed:'Minutes from the request until usable information was found.',documentFound:'Whether a usable source was found during the retrieval test.',totalEffort:'Total project person-hours, including work later identified as rework.',forcedStops:'Stops where meaningful project work could not continue.',avoidableReworkHours:'Hours repeated because the original brief, decision, information, or handoff was insufficient.',realignmentEvents:'Material pauses, reversals, or redirections caused by earlier misalignment.',avoidableMinutes:'Minutes spent on avoidable switching, copying, re-entry, or context reconstruction.',contributors:'Contributors represented by this workflow observation.',workdays:'Contributor workdays represented by this workflow observation.',purpose:'The unique operational job this tool is expected to perform.',classification:'The tool’s demonstrated operational utility and overlap.',accurate:'Whether transferred information matched the authoritative source.',complete:'Whether all required fields or records arrived.',timely:'Whether the transfer arrived within the required window.',manualIntervention:'Whether a person had to trigger, repair, reconcile, or complete the transfer.',outcome:'Only successful and failed tests enter the integrity denominator.',failureReason:'Observed failure, missing evidence, or reason the test could not be completed.',workTransferred:'The work, decision, or deliverable passed between people or teams.',purposePresent:'Whether the handoff stated why the work was being transferred.',rationalePresent:'Whether the handoff explained the reasoning behind the request or decision.',ownerPresent:'Whether the receiving owner was explicit.',deadlinePresent:'Whether the required completion time was explicit.',constraintsPresent:'Whether material boundaries or limitations were supplied.',dependenciesPresent:'Whether prerequisites and dependent work were identified.',inputsPresent:'Whether the receiver had the materials needed to begin.',successCriteriaPresent:'Whether acceptable completion was defined.',contextLossRating:'How much context the receiver had to reconstruct, using the anchored 1–5 scale.',clarificationHours:'Combined active person-hours spent clarifying before confident progress.',missingContext:'Information that had to be recovered or reconstructed.',actualDuration:'Calendar days from start to independent performance of core recurring work.',calculatedValue:'Raw metric value produced from Day 3 samples.',state:'How this value was obtained and whether it is ready for final scoring.',estimatedValue:'A defensible practitioner estimate used when direct calculation is unavailable.',overrideValue:'Replacement raw value used only when the ordinary value is unsuitable.',sampleSize:'Number of observations or records supporting this metric.',evidenceBasis:'Evidence and sample records that justify this metric value.',overrideReason:'Why the ordinary value is unsuitable and the replacement is defensible.',estimationMethod:'How the estimate was produced and which assumptions it uses.',limitation:'Evidence gaps or constraints affecting interpretation.',title:'A short diagnostic label that remains meaningful outside this screen.',observation:'What the evidence shows without overstating causality.',structuralEffects:'Operating structures, roles, or information flows affected.',operationalConsequence:'The practical cost, delay, risk, or constraint created.',selectionRationale:'Why this is one of the most important entropy drivers.',evidenceIds:'Evidence records that substantiate this finding.',missingStructure:'The absent or ineffective operating structure being compensated for.',humanCompensation:'The recurring human behavior keeping work functional despite the gap.',whoCarriesIt:'The role or group bearing the compensating workload.',hiddenCost:'Time, attention, delay, or risk concealed by the workaround.',riskIfRemoved:'What would fail if the compensating behavior stopped.',level:'The recommendation horizon defined by the methodology.',priority:'Urgency based on operational risk and sequencing.',driverIds:'Selected entropy drivers this recommendation addresses.',structuralChange:'The concrete operating-system change being recommended.',expectedEffect:'The operational behavior or metric expected to improve.',successSignal:'Observable evidence that the recommendation is working.',executiveObservation:'Concise client-facing statement of the central diagnosis.',operationalImpact:'How the diagnosed conditions affect delivery, capacity, quality, or risk.',immediatePriority:'The first action the client should take after receiving the diagnosis.',scoreInterpretation:'What the OEI score means in this company’s operating context.',engagementPathway:'The appropriate next engagement or implementation path.'
};
const helpFor=(label,key)=>{const segment=key.split('.').at(-1),normalized=String(label).trim().toLowerCase();if(key.startsWith('reportDraft.dimensionNarratives.'))return'The client-facing interpretation of this dimension’s score and evidence.';if(FIELD_HELP[segment])return FIELD_HELP[segment];if(normalized==='estimate confidence')return'How defensible the estimate is before direct validation.';if(normalized==='diagnosis status')return'The engagement stage from readiness through delivery and closure.';if(normalized==='validation status')return'The result of testing this founder hypothesis against direct evidence.';if(normalized==='recent example or artifact')return'A concrete instance or record that can substantiate this interview response.';if(normalized==='what you heard, including the most recent example')return'The founder’s answer and a concrete recent instance, preserved as a hypothesis until validated.';return''};
const mandatory=key=>REQUIRED_PATHS.some(pattern=>pattern.test(key))||conditionalMandatory(key);
const labelText=(label,key,extra='')=>`${esc(label)}${mandatory(key)||extra.includes('required')?'<span class="required-mark" aria-hidden="true"> *</span>':''}`;
const field=(label,key,value='',type='text',extra='')=>{const pulled=extra.includes('data-pulled'),help=helpFor(label,key),helpId=`help-${key.replace(/[^a-z0-9]+/gi,'-')}`;return`<label class="field ${pulled?'pulled-field':''}"><span>${labelText(label,key,extra)}${pulled?'<em class="source-clue">From earlier evidence · editable</em>':''}</span>${type==='textarea'?`<textarea data-bind="${key}" ${help?`aria-describedby="${helpId}"`:''} ${extra}>${esc(value)}</textarea>`:`<input type="${type}" data-bind="${key}" value="${esc(value)}" ${help?`aria-describedby="${helpId}"`:''} ${extra}>`}${help?`<small class="field-help" id="${helpId}">${esc(help)}</small>`:''}</label>`};
const select=(label,key,value,values,placeholder=`Select ${label.toLowerCase()}…`,error='')=>{const help=helpFor(label,key),helpId=`help-${key.replace(/[^a-z0-9]+/gi,'-')}`;return`<label class="field"><span>${labelText(label,key)}</span><select data-bind="${key}" ${help?`aria-describedby="${helpId}"`:''}><option value="">${esc(placeholder)}</option>${values.map(option=>{const v=Array.isArray(option)?option[0]:option,l=Array.isArray(option)?option[1]:option;return`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`}).join('')}</select>${help?`<small class="field-help" id="${helpId}">${esc(help)}</small>`:''}${error?`<span class="validation-error" role="alert">${esc(error)}</span>`:''}</label>`};
const quantitativeControl=(prompt,key,value='',confidence='')=>prompt.quantitative?`<div class="quantitative-box"><div class="grid two"><label class="field"><span>Quantitative estimate<span class="required-mark" aria-hidden="true"> *</span></span><input type="number" data-bind="${key}.quantitativeEstimate" value="${esc(value)}" min="${prompt.quantitative.min??0}" ${prompt.quantitative.max!=null?`max="${prompt.quantitative.max}"`:''} step="${prompt.quantitative.step??'any'}"></label><div class="field fixed-unit"><span>Expected unit</span><strong>${esc(prompt.quantitative.unit)}</strong></div></div><p class="threshold-note">Reference: healthy ${esc(prompt.quantitative.healthy)} · severe ${esc(prompt.quantitative.severe)}. Use a defensible estimate; direct validation follows on Day 3.</p>${select('Estimate confidence',`${key}.confidence`,confidence,ENUMS.confidence,'Select confidence…')}</div>`:'';
const now=()=>new Date().toISOString();
function syncPromptEvidence(interviewIndex,sectionIndex){const interview=state.staffInterviews[interviewIndex],statement=interview.sectionArtifacts?.[sectionIndex]||'',existing=state.evidence.find(e=>e.sourceInterviewId===interview.id&&Number(e.sourceSectionIndex)===sectionIndex);if(existing){existing.statement=statement;existing.sourceEvidenceExists=true;existing.updatedAt=now();return}state.evidence.push(baseRecord('day2',{statement,evidenceType:'',metricIds:'',quantitativeEstimate:'',confidence:'',clientSafeWording:'',sourceInterviewId:interview.id,sourceSectionIndex:sectionIndex,sourceReference:`${interview.name||`Participant ${interviewIndex+1}`} · ${STAFF_INTERVIEW_SECTIONS[sectionIndex].title}`,sourceEvidenceExists:true,confirmed:false,contradictionSelected:false}))}
function setPath(path,value){const parts=path.split('.');let obj=state;for(let i=0;i<parts.length-1;i++){const part=parts[i];if(obj[part]==null||typeof obj[part]!=='object')obj[part]={};obj=obj[part]}obj[parts.at(-1)]=value;const founderMatch=path.match(/^founderIntake\.sections\.(f\d+)\.(.+)$/);if(founderMatch){const[id,key]=founderMatch.slice(1);if(key==='notApplicable'&&value)skipFounderSection(state,id);else if(key==='validationLeadRequested')syncFounderValidationLead(state,id,value);else if(state.founderIntake.sections[id].validationLeadRequested)syncFounderValidationLead(state,id,true)}const scheduledMatch=path.match(/^staffInterviews\.(\d+)\.scheduledTime$/);if(scheduledMatch&&value){const index=Number(scheduledMatch[1]),interview=state.staffInterviews[index];interview.status=interviewStatusAfterScheduling(interview.status,value);const statusControl=document.querySelector(`[data-bind="staffInterviews.${index}.status"]`);if(statusControl)statusControl.value=interview.status}const promptEvidenceMatch=path.match(/^staffInterviews\.(\d+)\.sectionEvidence\.(\d+)$/);if(promptEvidenceMatch&&value)syncPromptEvidence(Number(promptEvidenceMatch[1]),Number(promptEvidenceMatch[2]));const artifactMatch=path.match(/^staffInterviews\.(\d+)\.sectionArtifacts\.(\d+)$/);if(artifactMatch&&state.staffInterviews[Number(artifactMatch[1])].sectionEvidence?.[artifactMatch[2]])syncPromptEvidence(Number(artifactMatch[1]),Number(artifactMatch[2]));const contradictionMatch=path.match(/^evidence\.(\d+)\.contradictionSelected$/);if(contradictionMatch&&value&&state.evidence.filter(e=>e.contradictionSelected).length>2){state.evidence[Number(contradictionMatch[1])].contradictionSelected=false;toast='Select no more than two evidence records for a contradiction.'}state.updatedAt=now();state.workflowState.dirty=true;}
function download(name,content,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}function slug(s){return(s||'client').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}
async function hash(v){const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(v));return[...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}
function gate(){const configured=/^[a-f0-9]{64}$/i.test(window.OEI_ACCESS_CONFIG?.passphraseSha256||'');root.innerHTML=`<main class="gate"><section class="gate-card"><p class="eyebrow">Internal practitioner instrument</p><h1>OEI Diagnosis Workspace</h1><p>Run a complete four-day diagnosis without storing client data on a server.</p>${configured?`<form id="gate-form">${field('Session passphrase','passphrase','','password','autocomplete="current-password"')}<button class="btn">Enter workspace</button><p id="gate-error" class="small" role="alert"></p></form>`:`<div class="notice warning"><strong>Access configuration required.</strong><p>This static repository cannot provide secure authentication. Copy <code>access-config.example.js</code> to <code>access-config.js</code> during deployment and supply a SHA-256 passphrase digest. The local gate deters casual entry only; use protected hosting for real authentication.</p></div>`}<p class="small muted">No credentials or diagnosis data are persisted by the application. Access lasts for this tab only.</p></section></main>`;if(configured)document.querySelector('#gate-form').onsubmit=async e=>{e.preventDefault();const p=e.target.querySelector('input').value;if(await hash(p)===window.OEI_ACCESS_CONFIG.passphraseSha256.toLowerCase()){window.__oeiAccess=true;start()}else document.querySelector('#gate-error').textContent='Passphrase not accepted.'}}
function start(){root.className='app';renderStart()}
function renderStart(){state=null;root.innerHTML=`<main class="gate"><section class="gate-card"><p class="eyebrow">Workspace v${VERSIONS.workspaceVersion}</p><h1>Start a diagnosis</h1><div class="notice"><strong>Session-only privacy</strong><br>Diagnosis data stays in this browser tab unless you export a checkpoint or report. Refreshing or closing the page may remove unsaved work.</div><div class="actions" style="margin-top:1.3rem"><button class="btn" data-action="new">New diagnosis</button><label class="btn secondary">Import checkpoint<input id="import-start" type="file" accept=".json,application/json" hidden></label></div><hr style="border:0;border-top:1px solid var(--line);margin:1.5rem 0"><h2>Methodology information</h2><p class="small">Metric Dictionary ${VERSIONS.metricDictionaryVersion} · Scoring Engine ${VERSIONS.scoringSpecVersion} · Report Template ${VERSIONS.reportTemplateVersion} · Schema ${VERSIONS.schemaVersion}</p></section></main>`;document.querySelector('[data-action=new]').onclick=()=>{state=blankDiagnosis();view='overview';render()};document.querySelector('#import-start').onchange=e=>importFile(e.target.files[0])}
function progress(){const days=Object.values(state.workflowState.days);return Math.round(days.filter(x=>['complete','complete_with_limitations'].includes(x)).length/days.length*100)}function statusClass(s){return s==='complete'?'complete':s==='complete_with_limitations'?'limited':s==='not_started'?'':'progress'}
function shell(content){const nav=[['overview','Overview'],['day0','Day 0'],['day1','Day 1'],['day2','Day 2'],['day3','Day 3'],['day4','Day 4'],['report','Report']];root.innerHTML=`<header class="topbar"><div class="brand"><img src="/images/logo_OEI.png" alt=""><div><strong>${esc(state.engagement.companyName||'Untitled diagnosis')}</strong><small>OEI Diagnosis Workspace</small></div></div><div class="header-summary"><span>${esc(enumLabel('diagnosisStatus',state.engagement.status))}</span><span>${progress()}% complete</span><span>Checkpoint: ${state.workflowState.lastCheckpointExportAt?new Date(state.workflowState.lastCheckpointExportAt).toLocaleString():'not exported'}</span></div><div class="header-actions"><button class="btn secondary" data-action="checkpoint">Export checkpoint</button><button class="btn danger" data-action="close">Close &amp; clear</button></div><select class="mobile-nav" data-action="navigate">${nav.map(([id,l])=>`<option value="${id}" ${view===id?'selected':''}>${l}</option>`).join('')}</select></header><div class="shell"><aside class="sidebar" aria-label="Diagnosis sections">${nav.map(([id,l])=>`<button class="nav-button ${view===id?'active':''}" data-view="${id}"><span class="status-dot ${id==='overview'?'progress':statusClass(state.workflowState.days[id])}"></span>${l}</button>`).join('')}</aside><main id="main" class="main">${content}</main></div>${toast?`<div class="toast">${esc(toast)}</div>`:''}${modal||''}`;bindCommon()}
function head(title,subtitle,actions=''){const heading=`<div class="page-head"><div><p class="eyebrow">${esc(view==='overview'?'Engagement':view)}</p><h1 class="page-title">${esc(title)}</h1><p class="subtitle">${esc(subtitle)}</p></div><div class="actions no-print">${actions}</div></div>`;return view==='day3'?heading+validationLeadsPanel():heading}function dayAction(day){return`<select data-day-status="${day}" aria-label="${day} status">${ENUMS.workflowStatus.map(([v,l])=>`<option value="${v}" ${v===state.workflowState.days[day]?'selected':''}>${l}</option>`).join('')}</select>`}
function overview(){const score=calculateOEI(state.metricRecords),samples=Object.values(state.samples).flat().length;return head('Engagement overview','Identity, status, progress, and the next concrete action.')+`<div class="grid three"><div class="card"><span class="label">Day completion</span><div class="stat">${progress()}%</div></div><div class="card"><span class="label">Evidence and samples</span><div class="stat">${state.evidence.length+samples}</div></div><div class="card"><span class="label">Metrics final</span><div class="stat">${score.confirmedCount}/15</div></div></div><section class="card" style="margin-top:1rem"><h2>Engagement metadata</h2><div class="grid two">${field('Client or company name','engagement.companyName',state.engagement.companyName)}${field('Founder or sponsor','engagement.founderSponsor',state.engagement.founderSponsor)}${field('Primary contact','engagement.primaryContact',state.engagement.primaryContact)}${field('Practitioner','engagement.practitioner',state.engagement.practitioner)}${field('Start date','engagement.startDate',state.engagement.startDate,'date')}${field('Expected delivery date','engagement.deliveryDate',state.engagement.deliveryDate,'date')}${field('Company size','engagement.companySize',state.engagement.companySize)}${field('Business model','engagement.businessModel',state.engagement.businessModel)}${field('Communication platform','engagement.communicationPlatform',state.engagement.communicationPlatform)}${field('Documentation platform','engagement.documentationPlatform',state.engagement.documentationPlatform)}${field('Task-management platform','engagement.taskPlatform',state.engagement.taskPlatform)}${select('Diagnosis status','engagement.status',state.engagement.status,ENUMS.diagnosisStatus)}</div>${field('Confidentiality restrictions','engagement.confidentialityRestrictions',state.engagement.confidentialityRestrictions,'textarea')}${field('Practitioner notes (internal only)','engagement.practitionerNotes',state.engagement.practitionerNotes,'textarea')}${field('Current next action','engagement.nextAction',state.engagement.nextAction)}</section>`}
function day0(){return head('Engagement readiness','Confirm access, participation, scheduling, and evidence availability.',dayAction('day0'))+`<section class="card"><h2>Requirements checklist</h2>${REQUIREMENTS.map(([id])=>{const r=state.readiness.requirements[id];return`<div class="check-row"><div><strong>${esc(r.label)}</strong><br><span class="pill">${esc(r.category)}</span></div>${select('Status',`readiness.requirements.${id}.status`,r.status,ENUMS.requirementStatus,'Select requirement status…',validateRequirement(r)[0])}<div>${field('Notes / impact',`readiness.requirements.${id}.notes`,r.notes)}${field('Alternative source',`readiness.requirements.${id}.alternativeSource`,r.alternativeSource)}</div></div>`}).join('')}</section><section class="card" style="margin-top:1rem"><div class="record-head"><h2>Interview participants</h2><button class="btn secondary" data-add="interview">Add participant</button></div>${records('staffInterviews',['name','role','team','scheduledTime','status'])}</section>`}
function day1(){return head('Founder and system context','Use the questions as a conversational guide. Capture hypotheses here; validate them against evidence later.',dayAction('day1'))+`<section class="card"><h2>Founder intake</h2><p class="small muted">Open one question at a time. Create a validation lead when a founder claim or expected artifact should be tested on Day 3.</p>${Object.entries(state.founderIntake.sections).map(([id,s],i)=>{const prompt=FOUNDER_SECTIONS[i]||{title:s.title||s.label,question:s.question||s.label,followUps:[]};return`<details ${i===0?'open':''}><summary>${i+1}. ${esc(prompt.question)}</summary><p class="eyebrow prompt-topic">${esc(prompt.title)}</p>${prompt.followUps?.length?`<div class="probe-list"><strong>Useful probes</strong><ul>${prompt.followUps.map(probe=>`<li>${esc(probe)}</li>`).join('')}</ul></div>`:''}<label class="choice-line"><input type="checkbox" data-checkbox="founderIntake.sections.${id}.notApplicable" ${s.notApplicable?'checked':''}> Skip this question / not applicable</label><fieldset class="skippable-fields" ${s.notApplicable?'disabled':''}>${field('What you heard, including the most recent example',`founderIntake.sections.${id}.response`,s.response,'textarea')}${quantitativeControl(prompt,`founderIntake.sections.${id}`,s.quantitativeEstimate,s.confidence)}${field('Evidence or artifact to validate',`founderIntake.sections.${id}.artifactCandidate`,s.artifactCandidate)}<label class="choice-line validation-lead-choice"><input type="checkbox" data-checkbox="founderIntake.sections.${id}.validationLeadRequested" ${s.validationLeadRequested?'checked':''}> Create validation lead for Day 3</label>${s.validationLeadRequested&&!s.response?'<span class="validation-error" role="alert">Capture what you heard so the lead has a claim to validate.</span>':''}${field('Practitioner note',`founderIntake.sections.${id}.practitionerNote`,s.practitionerNote||'','textarea')}</fieldset>${s.notApplicable?field('Skip / not-applicable reason',`founderIntake.sections.${id}.skipReason`,s.skipReason,'textarea','required'):''}</details>`}).join('')}</section>`}
function day2(){const selectedEvidence=state.evidence.filter(e=>e.contradictionSelected).length;return head('Staff evidence','Use the 10 core questions in sequence. Open the probes only when useful; quantitative captures preserve the underlying OEI signals.',dayAction('day2'))+`<section class="card"><div class="record-head"><h2>Interviews</h2><button class="btn secondary" data-add="interview">Add interview</button></div>${state.staffInterviews.map((r,i)=>`<details><summary>${esc(r.name||`Participant ${i+1}`)} · ${esc(enumLabel('interviewStatus',r.status)||'Not scheduled')}</summary><div class="grid two">${field('Name or anonymous ID',`staffInterviews.${i}.name`,r.name,'text','data-pulled="true"')}${field('Role',`staffInterviews.${i}.role`,r.role,'text','data-pulled="true"')}${field('Team',`staffInterviews.${i}.team`,r.team,'text','data-pulled="true"')}${select('Status',`staffInterviews.${i}.status`,r.status,ENUMS.interviewStatus,'Select interview status…')}</div>${field('Confidentiality notes',`staffInterviews.${i}.confidentialityNotes`,r.confidentialityNotes,'textarea')}<h3>Guided interview · 10 core questions</h3><p class="small muted">Ask the numbered question conversationally. The original 27 topics remain available as optional probes and metric captures.</p>${STAFF_INTERVIEW_SECTIONS.map((section,j)=>{const prompts=section.promptIndexes.map(index=>STAFF_PROMPTS[index]),measures=section.promptIndexes.filter(index=>STAFF_PROMPTS[index].quantitative);return`<section class="interview-prompt"><h4>${j+1}. ${esc(section.question)}</h4><p class="prompt-topic">${esc(section.title)}</p><details class="probe-details"><summary>Useful probes from the full interview guide</summary><ul>${prompts.flatMap(prompt=>[prompt.question,...(prompt.followUps||[])]).map(probe=>`<li>${esc(probe)}</li>`).join('')}</ul></details>${field('Response',`staffInterviews.${i}.sectionResponses.${j}`,r.sectionResponses?.[j]||'','textarea')}${measures.length?`<details class="metric-captures"><summary>Quantitative captures (${measures.length})</summary>${measures.map(index=>quantitativeControl(STAFF_PROMPTS[index],`staffInterviews.${i}.sectionQuantitative.${j}.${index}`,r.sectionQuantitative?.[j]?.[index]?.quantitativeEstimate||'',r.sectionQuantitative?.[j]?.[index]?.confidence||'')).join('')}</details>`:''}${field('Recent example or artifact',`staffInterviews.${i}.sectionArtifacts.${j}`,r.sectionArtifacts?.[j]||'','textarea',r.sectionEvidence?.[j]?'required':'')}<label class="choice-line"><input type="checkbox" data-checkbox="staffInterviews.${i}.sectionEvidence.${j}" ${r.sectionEvidence?.[j]?'checked':''}> Evidence exists</label>${r.sectionEvidence?.[j]&&!r.sectionArtifacts?.[j]?'<span class="validation-error" role="alert">Add the recent example or artifact so the evidence record has a statement to validate.</span>':''}</section>`}).join('')}<button class="btn danger" data-remove="staffInterviews:${i}">Remove interview</button></details>`).join('')||'<div class="empty">Add 3–5 participants to begin.</div>'}</section><div class="grid two" style="margin-top:1rem"><section class="card"><div class="record-head"><div><h2>Evidence</h2><span class="small muted">Select up to two records to prepare a contradiction · ${selectedEvidence}/2 selected</span></div><button class="btn secondary" data-add="evidence">Add evidence</button></div>${records('evidence',['statement','evidenceType','metricIds','confidence','clientSafeWording'])}</section><section class="card"><div class="record-head"><h2>Contradictions</h2><button class="btn secondary" data-add="contradictions">${selectedEvidence===2?'Prepare from selected evidence':'Add contradiction'}</button></div>${records('contradictions',['title','sourceA','sourceB','description','resolution'])}</section></div>`}
function records(key,fields){const controlled={staffInterviews:{status:['interviewStatus','Select interview status…']},evidence:{evidenceType:['evidenceType','Select evidence type…'],confidence:['confidence','Select confidence…']},findings:{confidence:['confidence','Select confidence…']},recommendations:{level:['recommendationLevel','Select recommendation level…'],priority:['priority','Select priority…']}};return state[key].map((r,i)=>{const evidence=key==='evidence',statement=String(r.statement||''),preview=(statement||'Statement pending').replace(/\s+/g,' ').slice(0,90),open=evidence?`<details class="record evidence-record ${r.confirmed?'evidence-confirmed':''}"><summary><span>${esc(preview)}${statement.length>90?'…':''}</span><span class="pill ${r.confirmed?'good':'warn'}">${r.confirmed?'Confirmed':'Needs confirmation'}</span></summary>`:'<div class="record">',close=evidence?'</details>':'</div>';return`${open}${evidence?`<div class="evidence-actions"><label class="choice-line"><input type="checkbox" data-checkbox="evidence.${i}.confirmed" ${r.confirmed?'checked':''}> Confirm evidence</label><label class="choice-line evidence-select"><input type="checkbox" data-checkbox="evidence.${i}.contradictionSelected" ${r.contradictionSelected?'checked':''}> Select for contradiction</label></div>${r.sourceReference?`<p class="source-clue">Prepared from ${esc(r.sourceReference)}</p>`:''}`:''}${fields.map(f=>{const spec=controlled[key]?.[f],displayLabel=f==='clientSafeWording'?'Client-facing copy':f.replace(/([A-Z])/g,' $1');if(spec)return select(displayLabel,`${key}.${i}.${f}`,r[f]??'',ENUMS[spec[0]],spec[1],f==='confidence'&&!r[f]?'Confidence is required.':'');const pulled=key==='evidence'&&f==='statement'&&r.sourceReference||key==='contradictions'&&['title','sourceA','sourceB'].includes(f)&&r.evidenceIds?.length;return field(displayLabel,`${key}.${i}.${f}`,r[f]??'',['notes','description','statement','clientSafeWording','resolution','observation','structuralChange','evidenceBasis','expectedEffect','successSignal'].includes(f)?'textarea':f==='scheduledTime'?'datetime-local':'text',pulled?'data-pulled="true"':'')}).join('')}${key==='staffInterviews'&&r.status==='skipped'?field('Skip reason',`${key}.${i}.skipReason`,r.skipReason||'','textarea','required'):''}<button class="btn danger" data-remove="${key}:${i}">Remove</button>${close}`}).join('')||'<div class="empty">No records yet.</div>'}
function validationLeadsPanel(){const leads=state.validationLeads||[],active=leads.filter(lead=>!lead.inactive);return`<section class="card validation-leads"><div class="record-head"><div><h2>Founder validation leads</h2><span class="small muted">${active.length} active · hypotheses only; no scoring effect</span></div></div><p class="small muted">Validate each founder claim against direct evidence. Only validated or contradicted leads can prepare an Evidence record.</p>${leads.map((lead,i)=>`<details class="validation-lead ${lead.inactive?'validation-lead-inactive':''}"><summary><span>${esc(lead.sourceQuestion||lead.claim||`Validation lead ${i+1}`)}</span><span class="pill ${lead.inactive?'warn':lead.status==='validated'?'good':lead.status==='contradicted'?'warn':''}">${esc(lead.inactive?'Inactive':enumLabel('validationLeadStatus',lead.status))}</span></summary><p class="source-clue">Pulled from Day 1 · editable working copy</p>${lead.inactive?`<div class="notice warning"><strong>${esc(lead.inactiveReason||'Inactive')}</strong><p>This lead is excluded from active validation, calculations, and reports.</p></div>`:''}${field('Founder claim',`validationLeads.${i}.claim`,lead.claim,'textarea','data-pulled="true"')}${lead.quantitativeEstimate!==''?`<div class="grid two">${field('Founder estimate',`validationLeads.${i}.quantitativeEstimate`,lead.quantitativeEstimate,'number','data-pulled="true"')}<div class="field fixed-unit"><span>Expected unit</span><strong>${esc(lead.unit)}</strong></div></div>`:''}${field('Artifact or evidence to inspect',`validationLeads.${i}.artifactCandidate`,lead.artifactCandidate,'textarea','data-pulled="true"')}${select('Validation status',`validationLeads.${i}.status`,lead.status,ENUMS.validationLeadStatus,'Select validation status…')}${field('Validation notes',`validationLeads.${i}.validationNotes`,lead.validationNotes,'textarea')}${lead.evidenceId?`<p class="source-clue">Evidence prepared: ${esc(lead.evidenceId)}</p>`:''}<div class="actions">${!lead.inactive&&['validated','contradicted'].includes(lead.status)&&!lead.evidenceId?`<button class="btn secondary" data-prepare-lead="${i}">Prepare Evidence record</button>`:''}${lead.inactive?`<button class="btn secondary" data-reactivate-lead="${i}">Reactivate</button><button class="btn danger" data-remove-lead="${i}">Delete lead</button>`:''}</div></details>`).join('')||'<div class="empty">No validation leads yet. Create them from relevant Day 1 questions.</div>'}</section>`}
function prepareLeadEvidence(index){const lead=state.validationLeads[index];if(!lead||lead.inactive||!['validated','contradicted'].includes(lead.status)||lead.evidenceId)return;const evidence=baseRecord('day3',{statement:lead.claim,evidenceType:'',metricIds:'',quantitativeEstimate:lead.quantitativeEstimate,confidence:lead.confidence||'',clientSafeWording:'',sourceValidationLeadId:lead.id,sourceReference:`Day 1 validation · ${lead.sourceQuestion}`,confirmed:false,contradictionSelected:false});state.evidence.push(evidence);lead.evidenceId=evidence.id;lead.updatedAt=now();state.workflowState.dirty=true;toast='Evidence record prepared. Review and confirm it in the Day 2 Evidence panel.';render()}
function derived(){return deriveMetrics(state)}
const sampleFields={criticalOperations:['name','owner','founderMemoryDependent','classificationReason'],decisionEvents:['decision','blockedPersonHours','contributorsAffected','evidenceReference'],documents:['name','process','obsolescenceStatus','classificationReason'],retrievalTests:['informationRequested','participant','minutesElapsed','documentFound'],projects:['name','totalEffort','forcedStops','avoidableReworkHours','realignmentEvents'],toolWorkflows:['name','avoidableMinutes','contributors','workdays'],tools:['name','purpose','classification','classificationReason'],integrations:['name','accurate','complete','timely','manualIntervention','outcome','failureReason'],handoffs:['workTransferred','purposePresent','rationalePresent','ownerPresent','deadlinePresent','constraintsPresent','dependenciesPresent','inputsPresent','successCriteriaPresent','contextLossRating','clarificationHours','missingContext'],onboardingCases:['role','startDate','autonomyDate','actualDuration','confidence']};const sampleEnum={criticalOperations:{founderMemoryDependent:['founderMemory','Select founder-memory classification…']},documents:{obsolescenceStatus:['documentStatus','Select documentation status…']},retrievalTests:{documentFound:['yesNoAssessment','Select retrieval outcome…']},tools:{classification:['toolClassification','Select classification…']},integrations:{accurate:['yesNoAssessment','Select accuracy…'],complete:['yesNoAssessment','Select completeness…'],timely:['yesNoAssessment','Select timeliness…'],manualIntervention:['manualIntervention','Select intervention status…'],outcome:['integrationOutcome','Select integration outcome…']},handoffs:{purposePresent:['handoffPresence','Select purpose status…'],rationalePresent:['handoffPresence','Select rationale status…'],ownerPresent:['handoffPresence','Select owner status…'],deadlinePresent:['handoffPresence','Select deadline status…'],constraintsPresent:['handoffPresence','Select constraints status…'],dependenciesPresent:['handoffPresence','Select dependencies status…'],inputsPresent:['handoffPresence','Select inputs status…'],successCriteriaPresent:['handoffPresence','Select success-criteria status…'],contextLossRating:['contextLoss','Select context-loss rating…']},onboardingCases:{confidence:['confidence','Select confidence…']}};
function day3(){const derivation=derived(),d=derivation.values;return head('Direct validation','Record explicit samples and prepare every raw metric for synthesis.',dayAction('day3'))+`<section class="card"><h2>Sampling denominators</h2><div class="grid three">${field('Sampled contributors','engagement.sampledContributors',state.engagement.sampledContributors||'','number')}${field('Sampled weeks','engagement.sampledWeeks',state.engagement.sampledWeeks||'','number')}${field('Founder workdays','engagement.founderWorkdays',state.engagement.founderWorkdays||'','number')}${field('Qualifying founder interruptions','engagement.qualifyingInterruptions',state.engagement.qualifyingInterruptions||'','number')}${field('Project months sampled','engagement.monthsSampled',state.engagement.monthsSampled||'','number')}${field('Tool contributors','engagement.toolContributors',state.engagement.toolContributors||'','number')}${field('Tool workdays represented','engagement.toolWorkdays',state.engagement.toolWorkdays||'','number')}</div></section>${Object.entries(SAMPLE_TYPES).map(([key,label])=>`<section class="card" style="margin-top:1rem"><div class="record-head"><div><h2>${esc(label)}</h2><span class="small muted">${state.samples[key].length} records</span></div><button class="btn secondary" data-add-sample="${key}">Add record</button></div>${state.samples[key].map((r,i)=>`<details><summary>${esc(r.name||r.decision||r.informationRequested||r.workTransferred||r.role||`${label} ${i+1}`)}</summary>${sampleFields[key].map(f=>{const spec=sampleEnum[key]?.[f],label=f.replace(/([A-Z])/g,' $1');if(spec)return select(label,`samples.${key}.${i}.${f}`,r[f]??'',ENUMS[spec[0]],spec[1],key==='tools'&&f==='classification'?validateToolRecord(r)[0]:'');const type=['blockedPersonHours','minutesElapsed','totalEffort','forcedStops','avoidableReworkHours','realignmentEvents','avoidableMinutes','clarificationHours','actualDuration'].includes(f)?'number':['startDate','autonomyDate'].includes(f)?'date':['classificationReason','failureReason','missingContext'].includes(f)?'textarea':'text';return field(label,`samples.${key}.${i}.${f}`,r[f]??'',type)}).join('')}<button class="btn danger" data-remove-sample="${key}:${i}">Remove</button></details>`).join('')||'<div class="empty">No samples recorded.</div>'}</section>`).join('')}<section class="card" style="margin-top:1rem"><h2>Calculated raw metric preparation</h2><div class="table-wrap"><table><thead><tr><th>Metric</th><th>Calculated value</th><th>Action</th></tr></thead><tbody>${METRICS.map(m=>`<tr><td>${esc(m.label)}</td><td>${d[m.id]==null?'Unavailable':Number(d[m.id]).toFixed(2)} ${esc(m.unit)}${['implicit_logic','obsolescence_rate','integration_integrity','tool_utility'].includes(m.id)?`<br><span class="small muted">Denominator: ${derivation.samples[{implicit_logic:'founder',obsolescence_rate:'documents',integration_integrity:'integrations',tool_utility:'tools'}[m.id]].denominator}</span>`:''}</td><td><button class="btn secondary" data-use-derived="${m.id}" ${d[m.id]==null?'disabled':''}>Use in synthesis</button></td></tr>`).join('')}</tbody></table></div></section>`}
function radar(score){const cx=125,cy=125,r=80,at=(i,v)=>{const a=i/5*Math.PI*2-Math.PI/2;return[cx+Math.cos(a)*r*v/10,cy+Math.sin(a)*r*v/10]},poly=v=>DIMENSIONS.map((_,i)=>at(i,v).join(',')).join(' '),vals=DIMENSIONS.map((d,i)=>score.dimensions[d.id].score==null?null:at(i,score.dimensions[d.id].score));return`<svg class="radar" viewBox="0 0 250 250" role="img" aria-label="OEI dimension radar. ${DIMENSIONS.map(d=>`${d.label}: ${score.dimensions[d.id].score?.toFixed(1)??'missing'}`).join('; ')}">${[2,4,6,8,10].map(v=>`<polygon points="${poly(v)}" fill="none" stroke="#d9dfe3"/>`).join('')}${DIMENSIONS.map((_,i)=>{const p=at(i,10);return`<line x1="125" y1="125" x2="${p[0]}" y2="${p[1]}" stroke="#d9dfe3"/>`}).join('')}${vals.every(Boolean)?`<polygon points="${vals.map(p=>p.join(',')).join(' ')}" fill="rgba(91,122,146,.22)" stroke="#5b7a92" stroke-width="2"/>`:vals.map(p=>p?`<circle cx="${p[0]}" cy="${p[1]}" r="4" fill="#5b7a92"/>`:'').join('')}</svg>`}
function day4(){const score=calculateOEI(state.metricRecords);return head('Synthesis and scoring','Confirm evidence-backed metric values, reconcile limitations, and select final drivers.',dayAction('day4'))+`<section class="card score-hero"><div><span class="pill ${score.final?'good':'warn'}">${score.final?'Final':'Provisional'}</span><div class="score-number">${score.displayScore?.toFixed(1)??'—'}</div><strong>${esc(score.tier?.label||'Not scored')}</strong><p class="muted">${score.confirmedCount} of 15 metrics final</p></div>${radar(score)}</section><section class="card" style="margin-top:1rem"><h2>Metric review</h2>${score.metricResults.map(r=>{const m=state.metricRecords[r.id];return`<details><summary>${esc(r.label)} · <span class="metric-score">${r.score?.toFixed(1)??'—'}</span></summary><p class="small muted"><strong>Raw-value reference:</strong> healthy ${r.direction==='higher_worse'?'≤':'≥'} ${r.healthy}; severe ${r.direction==='higher_worse'?'≥':'≤'} ${r.severe} ${esc(r.unit)}. Permitted range: ${r.min}–${r.max??'no fixed maximum'}. Healthy values normalize to 2/10; severe values normalize to 10/10.</p><div class="grid three">${field('Calculated value',`metricRecords.${r.id}.calculatedValue`,m.calculatedValue,'number','data-pulled="true"')}${select('State',`metricRecords.${r.id}.state`,m.state,ENUMS.metricState,'Select metric state…')}${select('Confidence',`metricRecords.${r.id}.confidence`,m.confidence,ENUMS.confidence,'Select confidence…',!m.confidence?'Confidence is required.':'')}${field('Estimated value',`metricRecords.${r.id}.estimatedValue`,m.estimatedValue,'number')}${field('Override value',`metricRecords.${r.id}.overrideValue`,m.overrideValue,'number')}${field('Sample size',`metricRecords.${r.id}.sampleSize`,m.sampleSize)}</div>${field('Evidence basis',`metricRecords.${r.id}.evidenceBasis`,m.evidenceBasis,'textarea')}${m.state==='overridden'?field('Override reason',`metricRecords.${r.id}.overrideReason`,m.overrideReason,'textarea','required'):m.state==='estimated'?field('Estimation method',`metricRecords.${r.id}.estimationMethod`,m.estimationMethod,'textarea','required'):''}${m.state==='unavailable'?field('Unavailable limitation',`metricRecords.${r.id}.limitation`,m.limitation,'textarea','required'):field('Limitation',`metricRecords.${r.id}.limitation`,m.limitation,'textarea')}</details>`}).join('')}</section><section class="card" style="margin-top:1rem"><h2>Candidate drivers</h2><p class="small muted">Ranked numerical signals are candidates only. Select 3-5 and author the diagnostic rationale.</p>${score.driverCandidates.map(r=>`<div class="record"><strong>${esc(r.label)}</strong> · ${r.score.toFixed(1)}/10 · ${esc(enumLabel('confidence',r.record.confidence))} <button class="btn secondary" data-select-driver="${r.id}" ${state.selectedDrivers.some(d=>d.metricId===r.id)?'disabled':''}>Select driver</button></div>`).join('')||'<div class="empty">Confirm metrics to produce candidates.</div>'}</section><section class="card" style="margin-top:1rem"><h2>Selected drivers (${state.selectedDrivers.length}/3-5)</h2>${state.selectedDrivers.map((d,i)=>`<details open><summary>${esc(d.title||d.metricId)}</summary>${field('Driver title',`selectedDrivers.${i}.title`,d.title)}${field('Observation',`selectedDrivers.${i}.observation`,d.observation,'textarea')}${field('Structural effects',`selectedDrivers.${i}.structuralEffects`,d.structuralEffects,'textarea')}${field('Operational consequence',`selectedDrivers.${i}.operationalConsequence`,d.operationalConsequence,'textarea')}${field('Selection rationale',`selectedDrivers.${i}.selectionRationale`,d.selectionRationale,'textarea')}<button class="btn danger" data-remove="selectedDrivers:${i}">Remove</button></details>`).join('')}</section>${synthesisLists()}`}
function synthesisLists(){const specs=[['findings','Key findings',['title','observation','evidenceIds','confidence','clientSafeWording']],['compensatingMechanisms','Compensating mechanisms',['missingStructure','humanCompensation','whoCarriesIt','hiddenCost','riskIfRemoved','clientSafeWording']],['recommendations','Strategic recommendations',['title','level','priority','driverIds','structuralChange','evidenceBasis','expectedEffect','successSignal']]];return specs.map(([key,title,fields])=>`<section class="card" style="margin-top:1rem"><div class="record-head"><h2>${title}</h2><button class="btn secondary" data-add="${key}">Add</button></div>${records(key,fields)}</section>`).join('')}
function report(){const assembled=assembleReport(state,{draft:true});return head('Report builder','Review client-safe narrative, validate the export gate, and preview the complete report.',dayAction('report'))+`<section class="card no-print"><h2>Practitioner-authored content</h2>${field('Executive observation','reportDraft.executiveObservation',state.reportDraft.executiveObservation,'textarea')}${field('Operational impact','reportDraft.operationalImpact',state.reportDraft.operationalImpact,'textarea')}${field('Immediate priority','reportDraft.immediatePriority',state.reportDraft.immediatePriority,'textarea')}${field('Score interpretation','reportDraft.scoreInterpretation',state.reportDraft.scoreInterpretation,'textarea')}<div class="grid two">${DIMENSIONS.map(d=>field(`${d.label} narrative`,`reportDraft.dimensionNarratives.${d.id}`,state.reportDraft.dimensionNarratives[d.id]||'','textarea')).join('')}</div>${field('Engagement pathway rationale','reportDraft.engagementPathway',state.reportDraft.engagementPathway,'textarea')}<label><input type="checkbox" data-checkbox="reportDraft.clientSafeReviewed" ${state.reportDraft.clientSafeReviewed?'checked':''}> I reviewed all exportable content for client safety.</label><h3>Export gate</h3><ul class="validation-list">${assembled.validation.errors.map(x=>`<li class="error">${esc(x)}</li>`).join('')}${assembled.validation.warnings.map(x=>`<li class="warning">${esc(x)}</li>`).join('')||'<li>No warnings.</li>'}</ul><div class="actions"><button class="btn" data-action="print" ${assembled.validation.errors.length?'disabled':''}>Print / Save PDF</button><button class="btn secondary" data-action="markdown" ${assembled.validation.errors.length?'disabled':''}>Export Markdown</button><button class="btn secondary" data-action="draft-markdown">Export labeled draft</button></div></section><section class="card" style="margin-top:1rem">${assembled.html}</section>`}
function render(){if(!state)return renderStart();const content={overview,day0,day1,day2,day3,day4,report}[view]();shell(content)}
function bindCommon(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;state.workflowState.activeView=view;render()});document.querySelector('[data-action=navigate]')?.addEventListener('change',e=>{view=e.target.value;render()});document.querySelectorAll('[data-bind]').forEach(el=>el.onchange=e=>{setPath(el.dataset.bind,el.type==='number'&&el.value!==''?Number(el.value):el.value);if(el.tagName==='SELECT'||view==='day4'||view==='report')render()});document.querySelectorAll('[data-checkbox]').forEach(el=>el.onchange=()=>{const path=el.dataset.checkbox;setPath(path,el.checked);if(!/^staffInterviews\.\d+\.sectionEvidence\.\d+$/.test(path))render()});document.querySelectorAll('[data-day-status]').forEach(el=>el.onchange=()=>{state.workflowState.days[el.dataset.dayStatus]=el.value;state.lastCompletedStep=el.dataset.dayStatus;state.workflowState.dirty=true;render()});document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>add(b.dataset.add));document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{const[k,i]=b.dataset.remove.split(':');state[k].splice(Number(i),1);state.workflowState.dirty=true;render()});document.querySelectorAll('[data-add-sample]').forEach(b=>b.onclick=()=>{state.samples[b.dataset.addSample].push(baseRecord('day3'));render()});document.querySelectorAll('[data-remove-sample]').forEach(b=>b.onclick=()=>{const[k,i]=b.dataset.removeSample.split(':');state.samples[k].splice(Number(i),1);render()});document.querySelectorAll('[data-use-derived]').forEach(b=>b.onclick=()=>{state.metricRecords[b.dataset.useDerived].calculatedValue=Number(derived().values[b.dataset.useDerived].toFixed(4));state.metricRecords[b.dataset.useDerived].state='calculated';view='day4';render()});document.querySelectorAll('[data-select-driver]').forEach(b=>b.onclick=()=>{const m=METRICS.find(x=>x.id===b.dataset.selectDriver);state.selectedDrivers.push(baseRecord('day4',{metricId:m.id,title:m.label,observation:'',structuralEffects:'',operationalConsequence:'',selectionRationale:'',clientSafeWording:''}));render()});document.querySelector('[data-action=checkpoint]')?.addEventListener('click',exportCheckpoint);document.querySelector('[data-action=close]')?.addEventListener('click',closeDiagnosis);document.querySelector('[data-action=print]')?.addEventListener('click',()=>window.print());document.querySelector('[data-action=markdown]')?.addEventListener('click',()=>download(`${slug(state.engagement.companyName)}_oei_report.md`,reportMarkdown(state),'text/markdown'));document.querySelector('[data-action=draft-markdown]')?.addEventListener('click',()=>download(`${slug(state.engagement.companyName)}_oei_report_DRAFT.md`,reportMarkdown(state,{draft:true}),'text/markdown'))}
function add(key){const templates={interview:{name:'',role:'',team:'',scheduledTime:'',status:'not_scheduled',confidentialityNotes:'',responses:{},responseQuantitative:{},responseArtifacts:{},responseEvidence:{},sectionResponses:{},sectionQuantitative:{},sectionArtifacts:{},sectionEvidence:{}},evidence:{statement:'',evidenceType:'',metricIds:'',quantitativeEstimate:'',confidence:'',clientSafeWording:'',confirmed:false,contradictionSelected:false},contradictions:{title:'',sourceA:'',sourceB:'',description:'',resolution:''},findings:{title:'',observation:'',evidenceIds:'',confidence:'',clientSafeWording:''},compensatingMechanisms:{missingStructure:'',humanCompensation:'',whoCarriesIt:'',hiddenCost:'',riskIfRemoved:'',clientSafeWording:''},recommendations:{title:'',level:'',priority:'',driverIds:'',structuralChange:'',evidenceBasis:'',expectedEffect:'',successSignal:''}};const target=key==='interview'?'staffInterviews':key;if(key==='contradictions'){const selected=state.evidence.filter(e=>e.contradictionSelected);if(selected.length===2){const [a,b]=selected;templates.contradictions={title:'Evidence contradiction',sourceA:`${a.id}: ${a.statement||'Statement pending'}`,sourceB:`${b.id}: ${b.statement||'Statement pending'}`,description:'',resolution:'',evidenceIds:[a.id,b.id]};selected.forEach(e=>e.contradictionSelected=false)}}state[target].push(baseRecord(view,templates[key]||{}));render()}
function exportCheckpoint(){const stamp=new Date().toISOString();state.updatedAt=stamp;state.workflowState.lastCheckpointExportAt=stamp;state.workflowState.dirty=false;const check=validateCheckpoint(state);if(!check.valid)return alert(check.errors.join('\n'));if(!confirm('This checkpoint contains diagnosis working data and may include confidential client information. Store it securely. Continue?'))return;download(`${slug(state.engagement.companyName)}_oei_diagnosis_${state.lastCompletedStep||'active'}_${stamp.slice(0,10)}.checkpoint.json`,JSON.stringify(state,null,2),'application/json');render()}
function importFile(file){if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const parsed=JSON.parse(reader.result),check=validateCheckpoint(parsed);if(!check.valid)throw new Error(check.errors.join('\n'));if(check.warnings.length&&!confirm(`${check.warnings.join('\n')}\n\nImport without recalculating historical scores?`))return;if(state&&!confirm('Importing replaces the active in-memory diagnosis. Continue?'))return;const migration=migrateCheckpoint(parsed);state=migration.data;if(migration.warnings.length)alert(`Checkpoint imported with warnings:
${migration.warnings.map(w=>`${w.path}: ${w.message}`).join('\n')}`);view=state.workflowState.activeView||'overview';render()}catch(e){alert(`Checkpoint not imported:\n${e.message}`)}};reader.readAsText(file)}
function closeDiagnosis(){if(!confirm('Close and clear this diagnosis? Unsaved in-memory work will be removed. Export a checkpoint first if needed. Downloaded checkpoint files are not deleted.'))return;state=null;renderStart()}
root.addEventListener('click',event=>{const prepare=event.target.closest('[data-prepare-lead]');if(prepare){prepareLeadEvidence(Number(prepare.dataset.prepareLead));return}const reactivate=event.target.closest('[data-reactivate-lead]');if(reactivate){const lead=state.validationLeads[Number(reactivate.dataset.reactivateLead)],section=state.founderIntake.sections[lead.sourceSectionId];section.notApplicable=false;syncFounderValidationLead(state,lead.sourceSectionId,true);state.workflowState.dirty=true;render();return}const remove=event.target.closest('[data-remove-lead]');if(remove){const index=Number(remove.dataset.removeLead),lead=state.validationLeads[index],section=state.founderIntake.sections[lead.sourceSectionId];if(section)section.validationLeadRequested=false;state.validationLeads.splice(index,1);state.workflowState.dirty=true;render()}});
root.addEventListener('change',event=>{if(event.target.dataset.bind!=='engagement.sampledWeeks'||!state)return;state.engagement.monthsSampled=projectMonthsFromWeeks(event.target.value);const months=document.querySelector('[data-bind="engagement.monthsSampled"]');if(months)months.value=state.engagement.monthsSampled});
window.addEventListener('beforeunload',e=>{if(state?.workflowState?.dirty){e.preventDefault();e.returnValue=''}});if(window.__oeiAccess)start();else gate();
